package dev.zomboidmelee.boxing;
import java.util.*;import dev.zomboidmelee.boxing.Checks16.Stack;import net.minecraft.world.phys.*;import net.minecraft.client.Minecraft;import dev.zomboidmelee.boxing.Checks16.*;import com.armilp.ezweight.stamina.StaminaCommon;
public class CombatChecks18{
 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}public static class Data{Map<String,Long>values=new HashMap<>();public long getLong(String s){return values.getOrDefault(s,0L);}public void putLong(String s,long n){values.put(s,n);}public void remove(String k){values.remove(k);}}
 public static class Level extends World{public Map<Integer,Object>entities=new HashMap<>();public boolean wall;public static class Clip{boolean blocked;Clip(boolean b){blocked=b;}public String getType(){return blocked?"BLOCK":"MISS";}}public Clip clip(net.minecraft.world.level.ClipContext c){return new Clip(wall);}public int sounds,particles;public Object getEntity(int id){return entities.get(id);}public void playSound(Object p,Object at,Object event,Object source,float volume,float pitch){sounds++;}public void sendParticles(Object p,double x,double y,double z,int n,double a,double b,double c,double d){particles+=n;}}
 public static class Sources{public Object playerAttack(net.minecraft.world.entity.player.Player p){return p;}}
 public static class Actor extends net.minecraft.server.level.ServerPlayer{public Level w=new Level();public Vec3 eye=new Vec3(0,1.6,0),look=new Vec3(0,0,1);public boolean sight=true;public int resets;public Level level(){return w;}public Vec3 getEyePosition(){return eye;}public Vec3 getLookAngle(){return look;}public boolean hasLineOfSight(Object o){return sight;}public double distanceToSqr(Zombie v){return v.x*v.x+v.z*v.z;}public double distanceToSqr(Vec3 v){return v.x*v.x+v.y*v.y+v.z*v.z;}public Sources damageSources(){return new Sources();}public Object blockPosition(){return this;}public void resetAttackStrengthTicker(){resets++;}public double getX(){return 0;}public double getZ(){return 0;}}
 public static class Random{public float nextFloat(){return .01f;}}
 public static class Zombie extends net.minecraft.world.entity.LivingEntity{public Level w;public Data data=new Data();public Nav nav=new Nav();public double x=0,z=2,dx,dy,dz;public float yBodyRot;public float getBbWidth(){return 1.8f;}public int state,hits;public float damage;public boolean alive=true,hurtMarked,deny;public Zombie(Level w){this.w=w;}public Level level(){return w;}public Data getPersistentData(){return data;}public Nav getNavigation(){return nav;}public boolean isAlive(){return alive;}public double getX(){return x;}public double getZ(){return z;}public Vec3 position(){return new Vec3(x,0,z);}public AABB getBoundingBox(){return new AABB(x-.5,0,z-.5,x+.5,1.8,z+.5);}public Object blockPosition(){return this;}public Random getRandom(){return new Random();}public void push(double a,double b,double c){dx+=a;dy+=b;dz+=c;}public boolean jumping;public void setJumping(boolean v){jumping=v;}public boolean hurt(Object source,float amount){hits++;if(deny)return false;damage=amount;if(amount>1000)alive=false;else{Combat18.mark(this,w.time);Stomp18.recoil(this,source);}return true;}}
 public static class Knock{Zombie victim;public boolean canceled;Knock(Zombie z){victim=z;}public Zombie getEntity(){return victim;}public void setCanceled(boolean b){canceled=b;}}
 public static class Camera{float pitch=10,roll=2;public float getPitch(){return pitch;}public float getRoll(){return roll;}public void setPitch(float v){pitch=v;}public void setRoll(float v){roll=v;}}
 public static class Use{public boolean canceled;public boolean isAttack(){return false;}public boolean isUseItem(){return true;}public Object getHand(){return net.minecraft.world.InteractionHand.MAIN_HAND;}public void setCanceled(boolean b){canceled=b;}public void setSwingHand(boolean b){}}
 public static void main(String[]args){Actor p=new Actor();Zombie z=new Zombie(p.w);p.w.entities.put(1,z);Combat18.heavy(p,1);ok(z.damage==3&&p.resets==1&&p.w.sounds==2,"heavy damage and world sounds");ok(Combat18.NEXT.get(p)==118,"18 tick shared heavy cooldown");ok(z.dy==0&&z.dz>0,"horizontal push with zero added vertical impulse");ok(Stomp18.down(z)&&z.data.getLong("boxing18_down_until")==180,"temporary 4 second knockdown synced state");Knock k=new Knock(z);Combat18.knockback(k);ok(k.canceled,"native upward knockback canceled");p.w.time=102;k=new Knock(z);Combat18.knockback(k);ok(!k.canceled,"unrelated later knockback preserved");Combat18.heavy(p,1);ok(z.hits==1,"heavy spam rejected");ok(!Combat18.gate(p,z),"light cannot bypass heavy cooldown");p.w.time=118;ok(Combat18.gate(p,z),"light accepted after cooldown");ok(!Combat18.gate(p,z),"light spam rejected");
  p.w.time=130;p.w.wall=true;Combat18.heavy(p,1);ok(z.hits==1,"solid block on actual aim ray blocks punch");p.w.wall=false;p.sight=false;Combat18.heavy(p,1);ok(z.hits==1,"wall blocks heavy");p.sight=true;p.look=new Vec3(1,0,0);Combat18.heavy(p,1);ok(z.hits==1,"no aim assist outside actual ray");p.look=new Vec3(0,0,1);StaminaCommon.allow=false;Combat18.heavy(p,1);ok(z.hits==1,"stamina required");StaminaCommon.allow=true;p.main=new Stack(false);Combat18.heavy(p,1);ok(z.hits==1,"equipped item disables fists");p.main=new Stack(true);
  ok(Stomp18.roll(false,.119f)&&!Stomp18.roll(false,.12f)&&Stomp18.roll(true,.299f)&&!Stomp18.roll(true,.30f),"12% light / 30% heavy knockdown boundaries");p.eye=new Vec3(0,1.6,0);p.look=new Vec3(0,-1.25,1.05);double len=Math.sqrt(p.look.y*p.look.y+p.look.z*p.look.z);p.look=p.look.scale(1/len);ok(Stomp18.headAim(p,z),"close downward head aim accepted");p.look=new Vec3(0,0,1);ok(!Stomp18.headAim(p,z),"standing eye-level aim cannot stomp head");p.look=new Vec3(0,-1.25/len,1.05/len);p.w.time=150;z.deny=true;int before=z.state;Stomp18.stomp(p,1);ok(z.alive&&z.state==before,"canceled damage restores head, does not force death");z.deny=false;p.w.time=170;Stomp18.stomp(p,1);ok(!z.alive&&(z.state&1)!=0&&z.damage==Float.MAX_VALUE,"valid head stomp lethal, head removed");ok(p.w.particles==24,"head burst particles");
  Minecraft mc=Minecraft.INSTANCE;mc.player=p;BoxingClient16.CLOCK=()->1_080_000_000L;BoxingClient16.started=1_000_000_000L;BoxingClient16.heavy=false;Camera c=new Camera();BoxingClient16.camera(c);ok(c.pitch!=10&&Math.abs(c.pitch-10)<.46&&Math.abs(c.roll-2)<.21,"bounded camera-only light hit motion");BoxingClient16.heavy=true;c=new Camera();BoxingClient16.camera(c);ok(Math.abs(c.pitch-10)<1.11&&c.pitch!=10,"heavy camera motion");ok(BoxingClient16.cameraWave(2_000_000_000L,1_000_000_000L,true)==0,"camera returns to rest, no persistent wobble");p.main=new Stack(false);c=new Camera();BoxingClient16.camera(c);ok(c.pitch==10&&c.roll==2,"armed camera preserved");p.main=new Stack(true);mc.hitResult=new Hit("BLOCK");Use use=new Use();BoxingClient16.input(use);ok(!use.canceled,"right click block interaction retained");ok(p.x==5&&p.y==7&&p.z==9,"no player root displacement");
  Pose pose=new Pose();z.state=1<<30;BoxingClient16.prone(z,pose);ok(pose.translations.size()==1&&Math.abs(pose.translations.get(0)[2]+.8)<.001,"floor model centered in prone collision box");
  p.w.time=200;z.alive=true;z.state=1<<30;z.data.putLong("boxing18_down_until",210);z.jumping=true;dev.zomboid.gore.Knockdown18.tick(new Knock(z));ok(!z.jumping&&(z.state&(1<<30))!=0,"downed zombie cannot jump");p.w.time=210;dev.zomboid.gore.Knockdown18.tick(new Knock(z));ok((z.state&(1<<30))==0,"temporary knockdown expires without disabling legs");
  ok(!dev.zomboid.gore.Rules.crawling(1<<25)&&dev.zomboid.gore.Rules.crawling(1<<30),"knockdown bit does not overlap sniper torso exits");z.state=(1<<30)|48;z.data.putLong("boxing18_down_until",210);dev.zomboid.gore.Knockdown18.tick(new Knock(z));ok(z.state==48,"stand-up preserves preexisting leg injuries");
  System.out.println("HEAVY_COOLDOWN_SOUND_HORIZONTAL_RECOIL_KNOCKDOWN_HEAD_STOMP_CAMERA_CHECKS="+n);
 }
}
